 s=Session('stair',instance='/app/instance.npz');c=WBC(s)
 feet=c.feet.copy(); initial=feet.copy(); actions=[];hist=[]
 omega=np.sqrt(9.81/c.z0);step=-1;start=feet[0].copy();end=start.copy()
 for t in range(1000):
  time=t*.02
  if time<prep:
   u=time/prep
   # prepare right support and forward velocity
   com=c.com0.copy();com[0]+=.10*u*u;com[1]=-.08*u*u
   cv=np.array([.2*u/prep,-.16*u/prep,0]);contacts=[0,1]
  else:
   tm=time-prep;n=int(tm/T);u=(tm-n*T)/T;stance=(n+1)%2;swing=n%2
   if n!=step:
    step=n;start=feet[swing].copy();end=np.array([L*(n+1),width*(1 if swing==0 else -1),ground(L*(n+1))+.008])
   blend=u*u*(3-2*u)
   feet[swing]=start+(end-start)*blend
   feet[swing,2]+=lift*np.sin(np.pi*u)
   if u>.96:feet[swing]=end.copy()
   contacts=[stance]
   if u>.94:contacts=[0,1]
   # periodic inverted pendulum reference
   p=feet[stance];arg=omega*T*(u-.5);den=np.sinh(omega*T/2)
   com=np.array([p[0]+L/2*np.sinh(arg)/den,p[1]*(1-np.cosh(arg)/np.cosh(omega*T/2)),c.z0+height])
   cv=np.array([L/2*omega*np.cosh(arg)/den,-p[1]*omega*np.sinh(arg)/np.cosh(omega*T/2),0.])
   # smooth height with both supports
   zstart=ground(p[0]);zend=ground(end[0]);com[2]+=zstart+(zend-zstart)*blend
   cv[2]=(zend-zstart)*6*u*(1-u)/T
